  window.guardarMallaCurricularDocente = async (event, areaKey) => {
    event.preventDefault();
    const form = event.currentTarget;
    const boton = form.querySelector('button[type="submit"]');
    if (!boton || boton.disabled) return;
    const nivelInputs = [...form.querySelectorAll('[data-nivel-malla-docente]')];
    const malla = nivelInputs.map((grupo, indice) => ({
      nivel: grupo.dataset.nivelMallaDocente,
      modulos: [1, 2, 3, 4, 5].map(numero => [
        grupo.querySelector('#malla-cod-' + indice + '-' + numero)?.value.trim(),
        grupo.querySelector('#malla-nom-' + indice + '-' + numero)?.value.trim()
      ])
    }));
    if (malla.length !== 4 || malla.some(nivel => nivel.modulos.some(modulo => modulo.some(valor => !valor)))) {
      alert('Completa el código y el nombre de los 20 módulos.');
      return;
    }
    boton.disabled = true;
    try {
      const respuesta = await sincronizarCalifGoogleSheet('guardar-malla', {carreraKey: areaKey, malla});
      if (respuesta.status !== 'success') throw new Error('El servidor no confirmó la malla.');
      const areas = obtenerAreasTecnicasConfig();
      const area = areas.find(item => item.key === areaKey);
      if (area) {
        lsSet('cea_areas_tec', areas.map(item => item === area ? {...item, malla} : item));
      }
      if (window._modoEdicionMallaDocente && form.isConnected) toggleEdicionMallaDocente();
      alert('Malla curricular guardada.');
    } catch (error) {
      if (!error.ceaReported || error.code === 'OCUPADO') alert(error.message);
    } finally {
      boton.disabled = false;
    }
  };


