  function buscarCarreraOficial(keyOrName) {
    const poolOficial = (typeof window !== 'undefined' && Array.isArray(window.BASE_CARRERAS_20) && window.BASE_CARRERAS_20.length > 0)
      ? window.BASE_CARRERAS_20
      : ((typeof BASE_CARRERAS_20 !== 'undefined' && Array.isArray(BASE_CARRERAS_20))
          ? BASE_CARRERAS_20
          : ((typeof AREAS_TEC_DEFAULT !== 'undefined' && Array.isArray(AREAS_TEC_DEFAULT)) ? AREAS_TEC_DEFAULT : []));
    const raw = String(keyOrName || '').trim();
    const norm = normalizarCadena(raw).replace(/^tec-?/, '');
    const pool = (typeof BASE_CARRERAS_20 !== 'undefined' && Array.isArray(BASE_CARRERAS_20))
      ? BASE_CARRERAS_20
      : ((typeof AREAS_TEC_DEFAULT !== 'undefined' && Array.isArray(AREAS_TEC_DEFAULT)) ? AREAS_TEC_DEFAULT : []);

    let found = pool.find(c => {
      const cKeyNorm = normalizarCadena(c.key).replace(/^tec-?/, '');
      const cNomNorm = normalizarCadena(c.nombre);
      return cKeyNorm === norm || cNomNorm === norm || norm.includes(cKeyNorm) || cKeyNorm.includes(norm) || norm.includes(cNomNorm) || cNomNorm.includes(norm);
    });

    if (!found) {
      for (const k in MALLAS_TECNICAS_DEFAULT_MAP) {
        const item = MALLAS_TECNICAS_DEFAULT_MAP[k];
        const iKeyNorm = normalizarCadena(item.key).replace(/^tec-?/, '');
        const iNomNorm = normalizarCadena(item.nombre);
        if (iKeyNorm === norm || iNomNorm === norm || norm.includes(iKeyNorm) || iKeyNorm.includes(norm) || norm.includes(iNomNorm) || iNomNorm.includes(norm)) {
          found = item;
          break;
        }
      }
    }

    if (!found) {
      found = pool[0] || MALLAS_TECNICAS_DEFAULT_MAP['tec-sis'];
    }
    return found;
  }

  function obtenerMallaOficialHumanistica(areaKey, nivel) {
    const guardada = lsGet('cea_malla_' + areaKey, []);
    const malla = Array.isArray(guardada) ? guardada : [];
    const curso = malla.find(item => normalizarNivelCanonica(item.nivel) === normalizarNivelCanonica(nivel));
    return [1, 2].map(numero => {
      const codigo = numero === 1 ? areaKey : areaKey + '-M2';
      const guardado = curso?.modulos?.find(item => (Array.isArray(item) ? item[0] : item.codigo) === codigo);
      const nombre = (Array.isArray(guardado) ? guardado[1] : guardado?.nombre) || 'Módulo ' + numero;
      return {codigo, nombre, completo: nombre + ' - ' + nivel, areaKey, numero};
    });
  }

  function numeroModuloHumanisticoCalif(registro) {
    return /-M2\b/i.test(String(registro.moduloCodigo || '')) || /-HUM[A-Z0-9]*M2-\d{4}-S[12]-P/i.test(String(registro.id || '')) ? 2 : 1;
  }

  function selectorModulosHumanisticaCalif(registro, modo, editable) {
    const areaKey = registro.areaKey || registro.carreraAreaKey;
    const modulos = obtenerMallaOficialHumanistica(areaKey, registro.nivel);
    const numero = numeroModuloHumanisticoCalif(registro);
    return `<div class="calif-modulo-tabs-bar-wrap">
      <div class="calif-modulo-tabs-bar">${modulos.map(modulo => `<button type="button" class="calif-modulo-tab-btn ${modulo.numero === numero ? 'active' : ''}" onclick="window.cambiarModuloPlanilla(${argumentosCalif(areaKey, registro.nivel, modulo.codigo, modulo.nombre, registro.paralelo || 'A', modo)})">
        <span class="calif-modulo-tab-num">MÓDULO ${modulo.numero}</span><span class="calif-modulo-tab-name">${escapeHTML(modulo.nombre)}</span></button>`).join('')}</div>
      ${editable ? `<div style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-top:12px">
        <label>Nombre del módulo ${numero}<input class="calif-filter-input" data-nombre-modulo-humanistica maxlength="160" placeholder="Escribe el nombre del módulo" value="${escapeHTML(/^Módulo [12]$/.test(modulos[numero - 1].nombre) ? '' : modulos[numero - 1].nombre)}"></label>
        <button type="button" class="btn-calif btn-calif-secondary" onclick="window.guardarNombreModuloHumanistica(this)">Guardar nombre</button>
        <span data-estado-nombre-modulo role="status"></span></div>` : ''}</div>`;
  }

  window.guardarNombreModuloHumanistica = async boton => {
    if (boton.disabled || !guardarAntesDeCambiarPlanilla()) return;
    const registro = _registroActivo;
    if (registro?.tipo !== 'humanistica') return;
    const bloque = boton.closest('.calif-modulo-tabs-bar-wrap');
    const nombre = bloque.querySelector('[data-nombre-modulo-humanistica]').value.trim();
    const estado = bloque.querySelector('[data-estado-nombre-modulo]');
    if (!nombre) { estado.textContent = 'Escribe el nombre del módulo.'; return; }
    boton.disabled = true;
    estado.textContent = 'Guardando…';
    try {
      await sincronizarCalifGoogleSheet('guardar-malla', {carreraKey: registro.areaKey,
        moduloHumanistico: {nivel: registro.nivel, numero: numeroModuloHumanisticoCalif(registro), nombre}});
      await cargarDatosGoogleSheets(true);
      if (_registroActivo?.id === registro.id) {
        const resultado = obtenerOCrearRegistro({...registro, registroId: registro.id}, registro.semestre, registro.gestion, registro.paralelo);
        renderPlanillaEvaluacion(resultado.registro, resultado.detalles, getSessionSegura().role === 'docente' ? 'docente' : 'director', {preserveScroll: true});
      }
    } catch (error) {
      estado.textContent = error.message || 'No se pudo guardar el nombre.';
    } finally { boton.disabled = false; }
  };

  function obtenerMallaOficialTecnica(carreraKey, nivelNombre) {
    const car = obtenerAreasTecnicasConfig().find(area => area.key === carreraKey) || buscarCarreraOficial(carreraKey);
    const malla = lsGet('cea_malla_' + carreraKey, null) || car?.malla;
    const nivelNorm = normalizarCadena(nivelNombre);
    let itemNivel = null;
    if (Array.isArray(malla)) {
      itemNivel = malla.find(m => normalizarCadena(m.nivel) === nivelNorm);
      if (!itemNivel) {
        if (nivelNorm.endsWith(' ii') || nivelNorm.includes('medio 2') || nivelNorm.includes('segundo')) {
          itemNivel = malla.find(m => normalizarCadena(m.nivel).endsWith(' ii'));
        } else if (nivelNorm.endsWith(' i') || nivelNorm.includes('medio 1') || nivelNorm.includes('primero')) {
          itemNivel = malla.find(m => normalizarCadena(m.nivel).endsWith(' i') && !normalizarCadena(m.nivel).endsWith(' ii'));
        } else {
          itemNivel = malla.find(m => normalizarCadena(m.nivel).includes(nivelNorm) || nivelNorm.includes(normalizarCadena(m.nivel)));
        }
      }
    }
    const oficial = buscarCarreraOficial(carreraKey);
    const base = oficial?.malla?.find(item => normalizarNivelCanonica(item.nivel) === normalizarNivelCanonica(nivelNombre));
    const personalizados = Array.isArray(itemNivel?.modulos) ? itemNivel.modulos : [];
    const nivel = NIVELES_TECNICOS_OFICIALES.findIndex(item => normalizarNivelCanonica(item) === normalizarNivelCanonica(nivelNombre));
    const romanos = ['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'];
    const mallaSistemas = mallaSistemasCalif(carreraKey, nivelNombre);
    return Array.from({length: 5}, (_, idx) => {
      const posicion = Math.max(0, nivel) * 5 + idx;
      const m = mallaSistemas
        ? (idx === 2 || idx === 3 ? mallaSistemas[idx] : personalizados.find(item =>
          numeroModuloCalif(Array.isArray(item) ? item[0] : item?.codigo) === posicion + 1) || mallaSistemas[idx])
        : personalizados[idx] || base?.modulos?.[idx];
      const cod = (Array.isArray(m) ? m[0] : m?.codigo) || ('Módulo ' + romanos[posicion]);
      const nom = (Array.isArray(m) ? m[1] : m?.nombre) || 'Módulo ' + romanos[posicion];
      return {
        codigo: cod,
        nombre: nom,
        completo: `${cod}: ${nom}`
      };
    });
  }

  function obtenerDocenteLogueado() {
    let session = null;
    if (typeof lsGet === 'function') {
      session = lsGet('cea_session', null) || lsGet('cea_sesion_activa', null);
    } else if (typeof localStorage !== 'undefined') {
      try {
        session = JSON.parse(localStorage.getItem('cea_session') || localStorage.getItem('cea_sesion_activa') || 'null');
      } catch (e) {}
    }
    if (!session && window._docAreaKeyActiva) {
      return {
        role: 'docente',
        name: 'Docente',
        areaKey: window._docAreaKeyActiva,
        token: ''
      };
    }
    if (!session) return null;
    return {
      role: session.role || 'docente',
      name: session.name || 'Docente',
      areaKey: session.areaKey || window._docAreaKeyActiva || '',
      token: session.token || ''
    };
  }

  /**
   * Resuelve las asignaciones oficiales reales del docente logueado
   */
  function obtenerAsignacionesDocente(docenteInfo) {
    const asignaciones = {
      tecnica: [],
      humanistica: []
    };

    if (!docenteInfo) return asignaciones;
    const { name, areaKey, role } = docenteInfo;
    const nameNorm = normalizarCadena(name);
    const keyNorm = normalizarCadena(areaKey);
    const esModoDocente = (role === 'docente');
    const esAreaHumanistica = keyNorm.startsWith('hum') || keyNorm.includes('social') || keyNorm.includes('natural') || keyNorm.includes('matematica') || keyNorm.includes('lenguaje');

    const areasTec = (typeof lsGet === 'function')
      ? lsGet('cea_areas_tec', (typeof AREAS_TEC_DEFAULT !== 'undefined' ? AREAS_TEC_DEFAULT : []))
      : (typeof AREAS_TEC_DEFAULT !== 'undefined' ? AREAS_TEC_DEFAULT : []);

    const docentesMap = (typeof lsGet === 'function')
      ? lsGet('cea_docentes', (typeof DOCENTES_DEFAULT !== 'undefined' ? DOCENTES_DEFAULT : {}))
      : (typeof DOCENTES_DEFAULT !== 'undefined' ? DOCENTES_DEFAULT : {});

    // 1. ASIGNACIONES TÉCNICAS (SOLO SI NO ES DOCENTE EXCLUSIVO DE HUMANÍSTICA)
    if (!esModoDocente || !esAreaHumanistica) {
      const nivelesTec = ['Técnico Básico', 'Técnico Auxiliar', 'Técnico Medio I', 'Técnico Medio II'];

      areasTec.forEach(carrera => {
        const docAsignadoCarrera = docentesMap[carrera.key] || carrera.docente || '';
        const docAsignadoNorm = normalizarCadena(docAsignadoCarrera);
        const carreraKeyNorm = normalizarCadena(carrera.key);
        const cKeyClean = carreraKeyNorm.replace(/^tec-?/, '');
        const kKeyClean = keyNorm.replace(/^tec-?/, '');
        const cNomNorm = normalizarCadena(carrera.nombre);

        const esMismaCarrera = (carreraKeyNorm === keyNorm) ||
                               (carrera.key === areaKey) ||
                               (cKeyClean && kKeyClean && (cKeyClean.includes(kKeyClean) || kKeyClean.includes(cKeyClean))) ||
                               (cNomNorm && kKeyClean && (cNomNorm.includes(kKeyClean) || kKeyClean.includes(cNomNorm)));

        const esDocenteAsignado = (role === 'director' || role === 'admin') ||
                                  esMismaCarrera ||
                                  (docAsignadoNorm && nameNorm && nameNorm.length > 4 && (docAsignadoNorm.includes(nameNorm) || nameNorm.includes(docAsignadoNorm)));

        if (esDocenteAsignado) {
          nivelesTec.forEach(nivelNombre => {
            const modulos = obtenerMallaOficialTecnica(carrera.key, nivelNombre);
            modulos.forEach(modItem => {
              asignaciones.tecnica.push({
                tipo: 'tecnica',
                areaKey: carrera.key,
                carrera: carrera.nombre,
                nivel: nivelNombre,
                moduloCodigo: modItem.codigo,
                moduloNombre: modItem.nombre,
                moduloCompleto: modItem.completo,
                docente: docAsignadoCarrera || name,
                color: carrera.color || 'var(--verde-dark)'
              });
            });
          });
        }
      });

      // Si por alguna razón la lista quedó vacía para el docente técnico, resolver directamente con carrera oficial
      if (asignaciones.tecnica.length === 0 && (!esModoDocente || !esAreaHumanistica)) {
        const carOficial = buscarCarreraOficial(areaKey || 'sistemas');
        nivelesTec.forEach(nivelNombre => {
          const modulos = obtenerMallaOficialTecnica(carOficial.key, nivelNombre);
          modulos.forEach(modItem => {
            asignaciones.tecnica.push({
              tipo: 'tecnica',
              areaKey: carOficial.key,
              carrera: carOficial.nombre,
              nivel: nivelNombre,
              moduloCodigo: modItem.codigo,
              moduloNombre: modItem.nombre,
              moduloCompleto: modItem.completo,
              docente: name || 'Docente',
              color: carOficial.color || 'var(--verde-dark)'
            });
          });
        });
      }
    }

    // 2. ASIGNACIONES HUMANÍSTICAS (SOLO SI NO ES DOCENTE EXCLUSIVO DE TÉCNICA)
    if (!esModoDocente || esAreaHumanistica) {
      const materiasHum = (typeof MATERIAS_HUMANISTICA !== 'undefined') ? MATERIAS_HUMANISTICA : [
        { area: 'CIENCIAS NATURALES', docente: 'Lic. Edmar Callisaya Tapia', clase: 'hum-cn' },
        { area: 'MATEMÁTICA Y ESTADÍSTICA', docente: 'Lic. Marcela Choque Mamani', clase: 'hum-mat' },
        { area: 'CIENCIAS SOCIALES', docente: 'Lic. María Estela Laura Tenorio', clase: 'hum-cs' },
        { area: 'LENGUAJE Y LITERATURA', docente: 'Lic. Efraina Pajarito Ventura', clase: 'hum-len' }
      ];

      materiasHum.forEach(mat => {
        const docAsignadoMateria = docentesMap[mat.clase] || mat.docente || '';
        const docAsignadoNorm = normalizarCadena(docAsignadoMateria);
        const claseNorm = normalizarCadena(mat.clase);

        const esDocenteAsignadoHum = (role === 'director' || role === 'admin') ||
                                     (claseNorm === keyNorm) ||
                                     (mat.clase === areaKey) ||
                                     (docAsignadoNorm && nameNorm && nameNorm.length > 4 && (docAsignadoNorm.includes(nameNorm) || nameNorm.includes(docAsignadoNorm)));

        if (esDocenteAsignadoHum) {
          NIVELES_HUMANISTICA_OFICIALES.forEach(nivHum => {
            asignaciones.humanistica.push({
              tipo: 'humanistica',
              areaKey: mat.clase,
              carrera: mat.area,
              materia: mat.area,
              nivel: nivHum.nivel,
              ciclo: nivHum.ciclo,
              curso: nivHum.curso,
              moduloCodigo: mat.clase,
              moduloNombre: mat.area,
              moduloCompleto: `${mat.area} — ${nivHum.nivel}`,
              docente: docAsignadoMateria || name,
              color: '#8b5cf6'
            });
          });
        }
      });
    }

    return asignaciones;
  }

  // ─── 4. OBTENCIÓN O CREACIÓN DE UN REGISTRO DE EVALUACIÓN ───
  function generarIdRegistro(asig, semestre, gestion, paralelo) {
    const k = asig.areaKey || 'area';
    const n = (asig.nivel || '').replace(/\s+/g, '-');
    const m = (asig.moduloCodigo || asig.moduloNombre || asig.materia || 'mod').replace(/[^a-zA-Z0-9]/g, '');
    const p = (paralelo || 'A').toUpperCase().replace(/[^a-zA-Z0-9]/g, '');
    const g = gestion || _gestionActiva || '2026';
    let sStr = semestre;
    if (!sStr) {
      sStr = (_semestreActivo || 'Primer Semestre');
    }
    const s = ceaPersistencia.period(sStr);
    return `REG-${k}-${n}-${m}-${g}-S${s}-P${p}`.toUpperCase();
  }

  function numeroModuloCalif(valor) {
    const codigo = normalizarCadena(valor).replace(/^(?:modulo|mod)[ ._-]*/, '').trim();
    const romanos = ['i','ii','iii','iv','v','vi','vii','viii','ix','x','xi','xii','xiii','xiv','xv','xvi','xvii','xviii','xix','xx'];
    return /^\d+$/.test(codigo) ? Number(codigo) : romanos.indexOf(codigo) + 1;
  }

  function mallaSistemasCalif(area, nivel) {
    if (!['tec-sis', 'tec-sistemas', 'sistemas', 'sistemas informaticos'].includes(normalizarCadena(area))) return null;
    return MALLAS_TECNICAS_DEFAULT_MAP['tec-sis'].malla
      .find(item => normalizarNivelCanonica(item.nivel) === normalizarNivelCanonica(nivel))?.modulos;
  }

  function numeroModuloRegistroCalif(registro) {
    const codigoId = String(registro.id || '').match(/-(?:m[oó]?dulo|mod)([ivx]+|\d+)-\d{4}-s[12]-p/i)?.[1];
    const numero = numeroModuloCalif(codigoId) || numeroModuloCalif(String(registro.moduloCodigo || '').split(':')[0]) ||
      numeroModuloCalif(String(registro.modulo || '').split(':')[0]);
    const malla = mallaSistemasCalif(registro.areaKey || registro.carreraAreaKey, registro.nivel);
    return malla && numero >= 1 && numero <= 5 ? numero + numeroModuloCalif(malla[0][0]) - 1 : numero;
  }

  function buscarPlanillaDelModulo(registros, asig, semestre, gestion, paralelo) {
    const normal = valor => normalizarCadena(String(valor || '')).trim();
    const area = valor => ({'tec-agr': 'tec-agropecuaria', 'tec-sistemas': 'tec-sis', sistemas: 'tec-sis', 'sistemas informaticos': 'tec-sis'})[normal(valor)] || normal(valor);
    const codigo = valor => normal(valor).replace(/^(?:modulo|mod)[ ._-]*/, '').replace(/[^a-z0-9]/g, '');
    const separar = valor => normal(valor).split(/\s*:\s*/, 2);
    const id = generarIdRegistro(asig, semestre, gestion, paralelo);
    const cod = codigo(asig.moduloCodigo);
    const nombre = normal(asig.moduloNombre);
    const completo = normal(asig.moduloCompleto);
    const candidatos = registros.filter(r => {
      if (area(r.areaKey || r.carreraAreaKey) !== area(asig.areaKey) ||
          normalizarNivelCanonica(r.nivel) !== normalizarNivelCanonica(asig.nivel) ||
          String(r.paralelo || 'A').trim().toUpperCase() !== paralelo ||
          !coincidePeriodoMatricula(r, gestion, semestre)) return false;
      if (asig.tipo === 'humanistica') return numeroModuloHumanisticoCalif(r) === numeroModuloHumanisticoCalif(asig);
      if (r.id === id) return true;
      const [prefijo, titulo] = separar(r.modulo);
      const numero = numeroModuloCalif(asig.moduloCodigo);
      const numeroGuardado = numeroModuloRegistroCalif(r);
      if (numero && numeroGuardado) return numero === numeroGuardado;
      if (r.id === asig.registroId) return true;
      const malla = mallaSistemasCalif(asig.areaKey, asig.nivel);
      if (malla && [malla[2], malla[3]].some(([clave]) => numeroModuloCalif(clave) === numero)) {
        return nombre && [normal(r.moduloNombre), titulo, normal(r.modulo)].includes(nombre);
      }
      return Boolean((completo && normal(r.modulo) === completo) ||
        (nombre && [normal(r.moduloNombre), titulo, normal(r.modulo)].includes(nombre)) ||
        (cod && [codigo(separar(r.moduloCodigo)[0]), codigo(prefijo)].includes(cod)));
    });
    return candidatos.sort((a, b) =>
      String(b.fechaModificacion || '').localeCompare(String(a.fechaModificacion || '')) ||
      Number(b.id === id) - Number(a.id === id))[0];
  }

  function obtenerOCrearRegistro(asig, semestre = null, gestion = null, paralelo = 'A', activar = true) {
    if (asig.tipo === 'humanistica') {
      const modulo = obtenerMallaOficialHumanistica(asig.areaKey, asig.nivel)[numeroModuloHumanisticoCalif(asig) - 1];
      asig = {...asig, moduloCodigo: modulo.codigo, moduloNombre: modulo.nombre, moduloCompleto: modulo.completo};
    }
    const g = gestion || _gestionActiva || '2026';
    let s = semestre;
    if (!s) {
      s = (_semestreActivo || 'Primer Semestre');
    }
    const p = String(paralelo || _paraleloActivo || 'A').trim().toUpperCase();
    let id = asig.registroId || generarIdRegistro(asig, s, g, p);
    const registros = getRegistros();
    let reg = buscarPlanillaDelModulo(registros, asig, s, g, p);

    if (!reg) {
      reg = {
        id: id,
        tipo: asig.tipo,
        areaKey: asig.areaKey,
        carrera: asig.carrera,
        nivel: asig.nivel,
        modulo: asig.moduloCompleto,
        moduloCodigo: asig.moduloCodigo || '',
        moduloNombre: asig.moduloNombre || asig.materia || '',
        docente: asig.docente,
        semestre: s,
        gestion: g,
        paralelo: p,
        fecha: new Date().toISOString().split('T')[0],
        estado: 'BORRADOR', // BORRADOR, EN EDICIÓN, FINALIZADO, PUBLICADO, ARCHIVADO
        bloqueado: false, // Control de bloqueo por Dirección
        estadoBloqueo: 'DESBLOQUEADO',
        usuarioBloqueo: '',
        fechaBloqueo: '',
        motivoBloqueo: '',
        criterios: asig.tipo === 'tecnica' ? CRITERIOS_TECNICA_DEFAULT : CRITERIOS_HUMANISTICA_DEFAULT,
        fechaCreacion: new Date().toISOString(),
        fechaModificacion: new Date().toISOString(),
        usuarioModif: asig.docente
      };
      registros.push(reg);
      setRegistros(registros);
      registrarAuditoria(id, 'CREAR', `Creación de registro para ${asig.carrera} - ${asig.nivel} - ${asig.moduloCompleto} (Gestión ${gestion} / ${semestre} / Par. ${paralelo})`);
    }

    id = reg.id;

    // Asegurar compatibilidad si el registro previo no tenía el campo bloqueado
    if (reg.bloqueado === undefined) reg.bloqueado = false;
    if (!reg.estadoBloqueo) reg.estadoBloqueo = reg.bloqueado ? 'BLOQUEADO' : 'DESBLOQUEADO';

    let todosDetalles = getDetalles();
    
    let detalles = detallesDePlanillaCalif(todosDetalles, id);

    // RECONCILIACIÓN AUTOMÁTICA AFILIACIÓN <-> LLENAR NOTAS BIDIRECCIONAL:
    // Asegurar que la nómina de detalles refleje fiel y exactamente los estudiantes afiliados
    // al curso y paralelo actual (preservando notas ya registradas).
    if (!reg.nominaVaciadaManual && typeof obtenerEstudiantesParaCurso === 'function') {
      const estsAfiliados = obtenerEstudiantesParaCurso(asig.areaKey, asig.nivel, p, g, s);
      if (Array.isArray(estsAfiliados) && estsAfiliados.length > 0) {
        let huboCambios = false;
        const nuevosDetalles = estsAfiliados.map((est, idx) => {
          const ciEst = est.ci ? String(est.ci).trim() : '';
          const rudeEst = est.rude ? String(est.rude).trim() : '';
          const nomEst = normalizarCadena(est.nombreCompleto || ((est.paterno || '') + ' ' + (est.materno || '') + ' ' + (est.nombres || '')));

          const dExistente = detalles.find(d => {
            const dCi = d.ci ? String(d.ci).trim() : '';
            const dRude = d.rude ? String(d.rude).trim() : '';
            const dNom = normalizarCadena((d.paterno ? (d.paterno + ' ' + (d.materno || '') + ' ' + d.nombres) : (d.nombreCompleto || d.nombres)) || '');
            if (ciEst && dCi && ciEst === dCi) return true;
            if (rudeEst && dRude && rudeEst === dRude) return true;
            if (!ciEst && !rudeEst && nomEst && nomEst === dNom) return true;
            return false;
          });

          if (dExistente) {
            return {
              ...dExistente,
              matriculaId: est.matriculaId || dExistente.matriculaId,
              nro: idx + 1,
              paterno: est.paterno || dExistente.paterno || '',
              materno: est.materno || dExistente.materno || '',
              nombres: est.nombres || est.nombreCompleto || dExistente.nombres || '',
              ci: est.ci || dExistente.ci || '',
              rude: est.rude || dExistente.rude || ''
            };
          } else {
            huboCambios = true;
            return {
              id: 'DET-' + reg.id + '-' + (est.matriculaId || (idx + 1)),
              matriculaId: est.matriculaId,
              idRegistro: reg.id,
              nro: idx + 1,
              paterno: est.paterno || '',
              materno: est.materno || '',
              nombres: est.nombres || est.nombreCompleto || '',
              ci: est.ci || '',
              rude: est.rude || '',
              ser: '',
              saber: '',
              hacer: '',
              decidir: '',
              autoevaluacion: '',
              numeral: '',
              cualitativa: '',
              observacion: ''
            };
          }
        });

        if (huboCambios) {
          const idsActivos = new Set(nuevosDetalles.map(d => d.id));
          todosDetalles = todosDetalles.filter(d => !idsActivos.has(d.id)).concat(nuevosDetalles);
          setDetalles(todosDetalles);
        }
        detalles = nuevosDetalles;
        reg.totalEstudiantes = detalles.length;
      } else if (Array.isArray(lsGet('cea_afiliacion_estudiantes', null))) {
        const prefijo = 'DET-' + reg.id + '-';
        detalles = detalles.filter(d => {
          const idDetalle = String(d.id || '');
          const vinculado = d.matriculaId || (idDetalle.startsWith(prefijo) &&
            /^(?:MAT-|[0-9a-f]{8}-[0-9a-f]{4}-)/i.test(idDetalle.slice(prefijo.length)));
          return !vinculado;
        });
        reg.totalEstudiantes = detalles.length;
      }
    }

    // Completar las notas de filas coincidentes dentro del mismo registro.
    if (Array.isArray(detalles) && detalles.length > 0 && Array.isArray(todosDetalles)) {
      detalles.forEach(d => {
        const ciNorm = d.ci ? String(d.ci).replace(/[^\d]/g, '') : '';
        const patNorm = normalizarCadena(d.paterno || '');
        const nomNorm = normalizarCadena(d.nombres || d.nombreCompleto || '');

        // Buscar coincidencia en todosDetalles que provenga de el sistema
        const matchRemoto = todosDetalles.find(r => {
          if (r === d) return false;
          const rCiNorm = r.ci ? String(r.ci).replace(/[^\d]/g, '') : '';
          const rPatNorm = normalizarCadena(r.paterno || '');
          const rNomNorm = normalizarCadena(r.nombres || '');
          const coincideEstudiante = (ciNorm && rCiNorm && ciNorm === rCiNorm) ||
                                     (d.rude && r.rude && String(d.rude).trim() === String(r.rude).trim()) ||
                                     (patNorm && nomNorm && rPatNorm === patNorm && rNomNorm === nomNorm);
          if (!coincideEstudiante) return false;

          // Si coincide el estudiante, verificar si es de este módulo o tiene notas ingresadas
          if (r.idRegistro) {
            const rRegNorm = normalizarCadena(r.idRegistro).replace(/[^a-zA-Z0-9]/g, '');
            if (r.idRegistro === reg.id) return true;
          }
          return false;
        });

        if (matchRemoto) {
          function parseVal(v) { return (v !== '' && v !== null && v !== undefined && !isNaN(Number(v))) ? Number(v) : null; }
          const vSer = parseVal(matchRemoto.ser);
          const vSab = parseVal(matchRemoto.saber);
          const vHac = parseVal(matchRemoto.hacer);
          const vDec = parseVal(matchRemoto.decidir);
          const vAuto = parseVal(matchRemoto.autoevaluacion);
          const vProc = parseVal(matchRemoto.proceso);
          const vProd = parseVal(matchRemoto.producto);
          const vFinal = parseVal(matchRemoto.notaFinal);

          if (vSer !== null) d.ser = vSer;
          if (vSab !== null) d.saber = vSab;
          if (vHac !== null) d.hacer = vHac;
          if (vDec !== null) d.decidir = vDec;
          if (vAuto !== null) d.autoevaluacion = vAuto;
          if (vProc !== null) d.proceso = vProc;
          if (vProd !== null) d.producto = vProd;

          if (vFinal !== null) {
            d.notaFinal = vFinal;
            d.numeral = vFinal;
          } else {
            // Calcular nota final según dimensiones
            const totalCalc = (Number(d.ser) || 0) + (Number(d.saber) || 0) + (Number(d.hacer) || 0) + (Number(d.decidir) || 0) + (Number(d.autoevaluacion) || 0);
            if (totalCalc > 0) {
              d.notaFinal = totalCalc;
              d.numeral = totalCalc;
            }
          }
          d.observacionManual = matchRemoto.observacionManual || d.observacionManual;
          d.estadoParticipante = matchRemoto.estadoParticipante || d.estadoParticipante;
          for (const campo of ['ser','saber','hacer','decidir','proceso','producto','autoevaluacion']) {
            if (matchRemoto[campo] === '') d[campo] = '';
          }
          if (matchRemoto.observacion) {
            d.observacion = matchRemoto.observacion === 'APROBADO' ? 'PROMOVIDO' :
                            matchRemoto.observacion === 'REPROBADO' ? 'POSTERGADO' : matchRemoto.observacion;
          }
          else if (Number(d.notaFinal) >= 51) d.observacion = 'PROMOVIDO';
          else if (Number(d.notaFinal) > 0) d.observacion = 'POSTERGADO';
        }
      });
    }

    detalles.forEach(detalle => {
      if (tieneDimensionesCalif(detalle, reg.tipo === 'tecnica')) calcularFilaEvaluacion(detalle, reg.tipo);
    });
    if (activar) {
      _registroActivo = reg;
      _detallesActivos = detalles;
      window._registroActivo = reg;
      window._detallesActivos = detalles;
    }
    return { registro: reg, detalles: detalles };
  }

  function cargarEstudiantesDesdeInscripciones(asig, reg) {
    if (typeof obtenerEstudiantesParaCurso === 'function') {
      const afiliados = obtenerEstudiantesParaCurso(asig.areaKey || asig.carrera, asig.nivel, reg.paralelo || 'A', reg.gestion, reg.semestre);
      if (Array.isArray(afiliados) && afiliados.length > 0) {
        return afiliados.map((item, idx) => ({
          id: 'DET-' + reg.id + '-' + (idx + 1),
          idRegistro: reg.id,
          nro: idx + 1,
          paterno: (item.paterno || '').toUpperCase(),
          materno: (item.materno || '').toUpperCase(),
          nombres: (item.nombres || '').toUpperCase(),
          ci: String(item.ci || '').trim(),
          rude: String(item.rude || item.codigoRude || '').trim(),
          ser: '',
          saber: '',
          decidir: '',
          proceso: '',
          producto: '',
          hacer: '',
          autoevaluacion: '',
          notaFinal: 0,
          observacion: 'PENDIENTE'
        }));
      }
    }
    return [];
  }

  // ─── 5. CÁLCULOS Y ESTADÍSTICAS OFICIALES ───
  function sumarDimensionesCalif(fila, tipo) {
    let final = 0;
    const num = (v) => {
      const parsed = parseFloat(v);
      return isNaN(parsed) ? 0 : parsed;
    };

    if (tipo === 'tecnica') {
      const ser = Math.min(10, Math.max(0, num(fila.ser)));
      const saber = Math.min(30, Math.max(0, num(fila.saber)));
      const decidir = Math.min(10, Math.max(0, num(fila.decidir)));
      const proceso = Math.min(20, Math.max(0, num(fila.proceso)));
      const producto = Math.min(20, Math.max(0, num(fila.producto)));
      const autoeval = Math.min(10, Math.max(0, num(fila.autoevaluacion)));
      final = Math.round(ser + saber + decidir + proceso + producto + autoeval);
    } else {
      const ser = Math.min(10, Math.max(0, num(fila.ser)));
      const saber = Math.max(0, num(fila.saber));
      const hacer = Math.max(0, num(fila.hacer === '' || fila.hacer == null ? fila.proceso : fila.hacer));
      const decidir = Math.min(10, Math.max(0, num(fila.decidir)));
      const autoeval = Math.min(10, Math.max(0, num(fila.autoevaluacion)));
      final = Math.round(ser + saber + hacer + decidir + autoeval);
    }

    return final;
  }

  function calcularFilaEvaluacion(fila, tipo = 'tecnica') {
    fila.notaFinal = sumarDimensionesCalif(fila, tipo);
    fila.observacion = observacionCalif(fila);


    return fila;
  }

  function calcularEstadisticasPlanilla(detalles) {
    const totalInscritos = detalles.length;
    let evaluados = 0;
    let aprobados = 0;
    let reprobados = 0;
    let pendientes = 0;
    let sumaNotas = 0;

    detalles.forEach(d => {
      const tieneNota = [d.ser, d.saber, d.decidir, d.proceso, d.producto, d.hacer, d.autoevaluacion]
        .some(v => v !== '' && v !== null && v !== undefined && !isNaN(parseFloat(v)));

      if (tieneNota && Number(d.notaFinal) > 0 && estadoParticipanteCalif(d) === 'EFECTIVO' && observacionCalif(d) !== 'RETIRADO') {
        evaluados++;
        const nota = d.notaFinal || 0;
        sumaNotas += nota;
        if (nota >= 51) aprobados++;
        else reprobados++;
      } else {
        pendientes++;
      }
    });

    const pctAprobacion = evaluados > 0 ? ((aprobados / evaluados) * 100).toFixed(1) + '%' : '0.0%';
    const pctReprobacion = evaluados > 0 ? ((reprobados / evaluados) * 100).toFixed(1) + '%' : '0.0%';
    const promedio = evaluados > 0 ? (sumaNotas / evaluados).toFixed(1) : '0.0';

    return {
      totalInscritos,
      evaluados,
      aprobados,
      reprobados,
      pendientes,
      pctAprobacion,
      pctReprobacion,
      promedio
    };
  }

