;

  window.publicarAvisoDocente = async function(e, docInfo) {
    if (e) e.preventDefault();
    const titulo = document.getElementById('aviso-doc-titulo')?.value || '';
    const categoria = document.getElementById('aviso-doc-categoria')?.value || 'Avisos';
    const desc = document.getElementById('aviso-doc-desc')?.value || '';
    const fecha = document.getElementById('aviso-doc-fecha')?.value || new Date().toISOString().split('T')[0];

    if (!titulo || !desc) return;

    const nuevoAviso = {
      id: 'ACT-' + Date.now(),
      titulo: titulo,
      categoria: categoria,
      descripcion: desc,
      fecha: fecha,
      autor: (docInfo && docInfo.name) || 'Docente Oficial',
      especialidad: (docInfo && (docInfo.carrera || docInfo.areaKey)) || 'General',
      gestion: _gestionActiva || '2026'
    };

    const actividades = (typeof lsGet === 'function') ? lsGet('cea_actividades', []) : [];
    actividades.unshift(nuevoAviso);
    if (typeof lsSet === 'function') lsSet('cea_actividades', actividades);
    else localStorage.setItem('cea_actividades', JSON.stringify(actividades));

    if (typeof renderFeedActividades === 'function') renderFeedActividades();
    if (typeof enviarGoogleSheet === 'function') {
      await enviarGoogleSheet({ action: 'guardar-actividad', actividad: nuevoAviso });
    }
    mostrarToastCalif('Aviso publicado institucionalmente y sincronizado.');
    conmutarVistaDocenteSidebar('avisos');
  };

