        carreraKey: 'sistemas',
        nivelesTec: ['Técnico Básico', 'Técnico Auxiliar', 'Técnico Medio I', 'Técnico Medio II'],
        modoHum: 'toda_area', // 'toda_area' o 'materia'
        materiaKey: 'hum-cn',
        nivelesHum: ['Aprendizajes Elementales', 'Aprendizajes Avanzados', 'Aprendizajes Aplicados', 'Aprendizajes Complementarios', 'Aprendizajes Especializados'],
        gestion: _gestionActiva || '2026',
