  // ─── FUNCIONES DIRECTAS DE AUDITORÍA Y REVISIÓN DE NOTAS DEL DIRECTOR ───
  function cerrarPlanillaEvaluacion(modo = 'director') {
    if (!guardarAntesDeCambiarPlanilla()) return;
    if (modo === 'director') {
      const p = document.getElementById('admin-planilla-container');
      if (p) {
        p.style.display = 'none';
        p.innerHTML = '';
      }
      const sub = document.getElementById('admin-calif-subtab-content');
      if (sub) {
        sub.style.display = 'block';
      }
      const aBody = document.getElementById('admin-stage-body');
      if (aBody) aBody.scrollTop = 0;
    } else {
      const p = document.getElementById('docente-planilla-container');
      if (p) {
        p.style.display = 'none';
        p.innerHTML = '';
      }
      const tree = document.getElementById('docente-cursos-container');
      if (tree) {
        tree.style.display = 'block';
      }
      const dMain = document.getElementById('docente-main-stage');
      if (dMain) dMain.scrollTop = 0;
    }
  }


  async function cambiarCursoEnPlanilla(selector, modo) {
    const origen = _registroActivo;
    const nivel = selector.value;
    if (!origen || nivel === origen.nivel) return;
    selector.disabled = true;
    try {
      const areaKey = origen.areaKey;
      const paralelos = getParalelosDisponibles(areaKey, nivel, origen.gestion, origen.semestre);
      const paralelo = paralelos.includes(origen.paralelo) ? origen.paralelo : paralelos[0];
      if (origen.tipo === 'tecnica') {
        const modulo = obtenerMallaOficialTecnica(areaKey, nivel)[0];
        if (modulo) await cambiarModuloPlanilla(areaKey, nivel, modulo.codigo, modulo.nombre, paralelo, modo);
      } else {
        if (!guardarAntesDeCambiarPlanilla()) return;
        const asignacion = {...origen, nivel, moduloCompleto: origen.carrera + ' - ' + nivel};
        const {registro, detalles} = obtenerOCrearRegistro(asignacion, origen.semestre, origen.gestion, paralelo);
        if (modo === 'director') {
          _matrizDirectorNav.nivel = nivel;
          _matrizDirectorNav.paralelo = paralelo;
        } else {
          _nivelActivoDocente = nivel;
          _paraleloActivo = paralelo;
        }
        renderPlanillaEvaluacion(registro, detalles, modo);
      }
    } finally {
      selector.value = origen.nivel;
      selector.disabled = false;
    }
  }
  window.cambiarCursoEnPlanilla = cambiarCursoEnPlanilla;

  function guardarAntesDeCambiarPlanilla() {
    if (!permitirSalirBoletin()) return false;
    if (!_registroActivo || !document.getElementById('tabla-eval-principal')) return true;
    if (!hayNotasPendientes(_registroActivo)) return true;
    if (!guardadosEnCursoCalif.has(_registroActivo)) {
      mostrarProgresoGuardadoCalif(_registroActivo, 'pendiente', 0, 'Pulsa Guardar antes de cambiar de planilla.');
    }
    return false;
  }

  async function cambiarModuloPlanilla(carreraKey, nivelNom, modCod, modNom, paralelo = 'A', modo = 'docente') {
    const origen = _registroActivo;
    if (!guardarAntesDeCambiarPlanilla()) return;

    const humanistica = String(carreraKey).startsWith('hum-');
    const malla = humanistica ? obtenerMallaOficialHumanistica(carreraKey, nivelNom) : obtenerMallaOficialTecnica(carreraKey, nivelNom);
    const modObj = malla.find(m => m.codigo === modCod || m.completo === `${modCod}: ${modNom}`) || { codigo: modCod, nombre: modNom, completo: `${modCod}: ${modNom}` };
    const carOficial = buscarCarreraOficial(carreraKey);

    const asig = {
      tipo: humanistica ? 'humanistica' : 'tecnica',
      areaKey: carreraKey,
      carrera: humanistica ? (origen?.carrera || 'Área Humanística') : carOficial?.nombre || 'Área Técnica',
      nivel: nivelNom,
      moduloCodigo: modObj.codigo,
      moduloNombre: modObj.nombre,
      moduloCompleto: modObj.completo,
      docente: _registroActivo?.docente || (obtenerDocenteLogueado()?.name || 'Docente'),
      color: carOficial?.color || 'var(--verde-dark)'
    };

    if (modo === 'docente') {
      _moduloActivoDocente = modObj.completo;
      _nivelActivoDocente = nivelNom;
      _paraleloActivo = paralelo || 'A';
    } else {
      _matrizDirectorNav.area = humanistica ? 'humanistica' : 'tecnica';
      _matrizDirectorNav.especialidadKey = carreraKey;
      _matrizDirectorNav.nivel = nivelNom;
      _matrizDirectorNav.paralelo = paralelo || 'A';
    }

    const { registro, detalles } = await obtenerOCrearRegistro(asig, origen?.semestre || _semestreActivo, origen?.gestion || _gestionActiva, paralelo || 'A');
    renderPlanillaEvaluacion(registro, detalles, modo);
  }

  async function abrirRegistroPrimerModuloDirector(carreraKey, nivelNom, paralelo = null) {
    if (!guardarAntesDeCambiarPlanilla()) return;
    const modulos = obtenerMallaOficialTecnica(carreraKey, nivelNom);
    const mod0 = modulos[0] || { codigo: 'MOD-01', nombre: 'Módulo 1: Fundamentos Aplicados' };
    const carOficial = buscarCarreraOficial(carreraKey);

    _matrizDirectorNav.area = 'tecnica';
    _matrizDirectorNav.especialidadKey = carOficial.key || carreraKey;
    _matrizDirectorNav.nivel = nivelNom;
    _matrizDirectorNav.paralelo = paralelo || getParalelosDisponibles(carOficial.key || carreraKey, nivelNom, _gestionActiva)[0];

    await abrirRegistroMatrizDirector(carOficial.key || carreraKey, nivelNom, mod0.codigo, mod0.nombre, 'tecnica');
  }

  async function abrirRegistroHumanisticaDirector(clase, nivelNom, paralelo = 'A') {
    if (!guardarAntesDeCambiarPlanilla()) return;
    const mats = (typeof MATERIAS_HUMANISTICA !== 'undefined') ? MATERIAS_HUMANISTICA : [];
    const materia = mats.find(m => m.clase === clase) || { area: 'Humanística' };
    _matrizDirectorNav.area = 'humanistica';
    _matrizDirectorNav.especialidadKey = clase;
    _matrizDirectorNav.nivel = nivelNom;
    _matrizDirectorNav.paralelo = paralelo || 'A';
    await abrirRegistroMatrizDirector(clase, nivelNom, clase, materia.area, 'humanistica');
  }

