  async function conmutarNotaSubidaEstudiante(carreraKey, nivelNom, paralelo, keyEst, estado) {
    const sKey = 'cea_subidas_' + carreraKey + '_' + nivelNom + '_' + (paralelo || 'A') + '_' + _gestionActiva + '_' + ceaPersistencia.period(_semestreActivo);
    const subidasMap = _getStorageItem(sKey, {});
    subidasMap[keyEst] = Boolean(estado);
    _setStorageItem(sKey, subidasMap);

    // Sincronización en segundo plano con el sistema
    const payloadSubida = {
      key: keyEst,
      estudianteKey: keyEst,
      carreraKey: carreraKey,
      nivel: nivelNom,
      nivelNombre: nivelNom,
      paralelo: paralelo || 'A',
      estado: Boolean(estado),
      subido: Boolean(estado),
      gestion: _gestionActiva,
      semestre: _semestreActivo,
      fechaHora: new Date().toISOString(),
      fechaActualizacion: new Date().toISOString()
    };
    await sincronizarCalifGoogleSheet('guardar-subida-estudiante', payloadSubida);

    
    const chk = (typeof document !== 'undefined' && typeof document.querySelector === 'function') ? document.querySelector(`input[data-subida-est="${keyEst}"]`) : null;
    const lbl = (typeof document !== 'undefined' && typeof document.getElementById === 'function') ? document.getElementById(`lbl-subida-${keyEst}`) : null;
    if (chk) chk.checked = Boolean(estado);
    if (lbl) {
      if (estado) {
        lbl.innerHTML = '<svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="#ffffff" stroke-width="3" style="display:inline-block;vertical-align:-1px;margin-right:2px"><polyline points="20 6 9 17 4 12"/></svg>SUBIDO';
        lbl.style.background = '#15803d';
        lbl.style.color = '#ffffff';
        lbl.style.border = '1.2px solid #15803d';
        lbl.style.boxShadow = '0 2px 5px rgba(21,128,61,0.30)';
      } else {
        lbl.textContent = 'PENDIENTE';
        lbl.style.background = '#f1f5f9';
        lbl.style.color = '#64748b';
        lbl.style.border = '1.2px solid #cbd5e1';
        lbl.style.boxShadow = 'none';
      }
    }
    if (chk) {
      const tr = chk.closest('tr');
      if (tr) {
        const idx = Array.from(tr.parentNode.children).indexOf(tr);
        if (estado) {
          tr.style.setProperty('background', '#bbf7d0', 'important');
          tr.style.setProperty('border-left', '6px solid #15803d', 'important');
          tr.style.setProperty('border-bottom', '1.5px solid #4ade80', 'important');
          tr.classList.remove('fila-impar', 'fila-par');
          tr.classList.add('fila-subida-confirmada');
        } else {
          const fondoCebra = (idx % 2 === 0) ? '#ffffff' : '#e2e8f0';
          const claseCebra = (idx % 2 === 0) ? 'fila-impar' : 'fila-par';
          tr.style.setProperty('background', fondoCebra, 'important');
          tr.style.setProperty('border-left', '6px solid transparent', 'important');
          tr.style.setProperty('border-bottom', '1.2px solid #cbd5e1', 'important');
          tr.classList.remove('fila-subida-confirmada');
          tr.classList.add(claseCebra);
        }
      }
    }
  }

  window.conmutarNotaSubidaEstudiante = conmutarNotaSubidaEstudiante;

  async function marcarTodosNotasSubidas(carreraKey, nivelNom, paralelo, marcarTodos) {
    const sKey = 'cea_subidas_' + carreraKey + '_' + nivelNom + '_' + (paralelo || 'A') + '_' + _gestionActiva + '_' + ceaPersistencia.period(_semestreActivo);
    const subidasMap = _getStorageItem(sKey, {});

    const itemsLote = [];
    if (typeof document !== 'undefined' && typeof document.querySelectorAll === 'function') {
      document.querySelectorAll(`input[data-subida-course="${carreraKey}_${nivelNom}_${paralelo}"]`).forEach(chk => {
        const k = chk.getAttribute('data-subida-est');
        if (k) {
          itemsLote.push({
            key: k,
            estudianteKey: k,
            carreraKey: carreraKey,
            nivel: nivelNom,
            nivelNombre: nivelNom,
            paralelo: paralelo || 'A',
            estado: Boolean(marcarTodos),
            subido: Boolean(marcarTodos),
            gestion: _gestionActiva,
            semestre: _semestreActivo,
            fechaHora: new Date().toISOString(),
            fechaActualizacion: new Date().toISOString()
          });
        }
      });
    }

    // Sincronización en segundo plano con el sistema
    await sincronizarCalifGoogleSheet('guardar-lote-subida-estudiantes', {
      carreraKey: carreraKey,
      nivel: nivelNom,
      nivelNombre: nivelNom,
      paralelo: paralelo || 'A',
      marcarTodos: Boolean(marcarTodos),
      items: itemsLote,
      gestion: _gestionActiva,
      semestre: _semestreActivo,
      fechaHora: new Date().toISOString(),
      fechaActualizacion: new Date().toISOString()
    });


    if (typeof document !== 'undefined' && typeof document.querySelectorAll === 'function') {
      document.querySelectorAll(`input[data-subida-course="${carreraKey}_${nivelNom}_${paralelo}"]`).forEach(chk => {
        chk.checked = Boolean(marcarTodos);
        const k = chk.getAttribute('data-subida-est');
        if (k) subidasMap[k] = Boolean(marcarTodos);
        const lbl = document.getElementById(`lbl-subida-${k}`);
        if (lbl) {
          if (marcarTodos) {
            lbl.innerHTML = '<svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="#ffffff" stroke-width="3" style="display:inline-block;vertical-align:-1px;margin-right:2px"><polyline points="20 6 9 17 4 12"/></svg>SUBIDO';
            lbl.style.background = '#15803d';
            lbl.style.color = '#ffffff';
            lbl.style.border = '1.2px solid #15803d';
            lbl.style.boxShadow = '0 2px 5px rgba(21,128,61,0.30)';
          } else {
            lbl.textContent = 'PENDIENTE';
            lbl.style.background = '#f1f5f9';
            lbl.style.color = '#64748b';
            lbl.style.border = '1.2px solid #cbd5e1';
            lbl.style.boxShadow = 'none';
          }
        }
        const tr = chk.closest('tr');
        if (tr) {
          const idx = Array.from(tr.parentNode.children).indexOf(tr);
          if (marcarTodos) {
            tr.style.setProperty('background', '#bbf7d0', 'important');
            tr.style.setProperty('border-left', '6px solid #15803d', 'important');
            tr.style.setProperty('border-bottom', '1.5px solid #4ade80', 'important');
            tr.classList.remove('fila-impar', 'fila-par');
            tr.classList.add('fila-subida-confirmada');
          } else {
            const fondoCebra = (idx % 2 === 0) ? '#ffffff' : '#e2e8f0';
            const claseCebra = (idx % 2 === 0) ? 'fila-impar' : 'fila-par';
            tr.style.setProperty('background', fondoCebra, 'important');
            tr.style.setProperty('border-left', '6px solid transparent', 'important');
            tr.style.setProperty('border-bottom', '1.2px solid #cbd5e1', 'important');
            tr.classList.remove('fila-subida-confirmada');
            tr.classList.add(claseCebra);
          }
        }
      });
    }

    _setStorageItem(sKey, subidasMap);
  }
  window.marcarTodosNotasSubidas = marcarTodosNotasSubidas;

  function conmutarBloqueoCursoDirector(carreraKey, nivelNom, paralelo, bloquear) {
    const todosRegs = getRegistros();
    let modifCount = 0;
    todosRegs.forEach(r => {
      const matchCar = (r.carreraAreaKey === carreraKey || r.areaKey === carreraKey || normalizarCadena(r.carrera) === normalizarCadena(carreraKey));
      if (matchCar && r.nivel === nivelNom && (r.paralelo || 'A') === (paralelo || 'A') && String(r.gestion) === String(_gestionActiva)) {
        r.bloqueado = Boolean(bloquear);
        r.estadoBloqueo = bloquear ? 'BLOQUEADO' : 'DESBLOQUEADO';
        r.fechaModificacion = new Date().toISOString();
        modifCount++;
      }
    });
    setRegistros(todosRegs);
    alert(bloquear ? 'Curso bloqueado contra modificaciones.' : 'Curso desbloqueado para edición.');
    renderSubtabAdminContenido();
  }
  window.conmutarBloqueoCursoDirector = conmutarBloqueoCursoDirector;

  function publicarNotasCursoDirector(carreraKey, nivelNom, paralelo) {
    const conf = confirm('¿Confirmas la publicación oficial de todas las notas de este curso/nivel?\n\nAl publicar, el estado cambiará a NOTAS PUBLICADAS.');
    if (!conf) return;

    const todosRegs = getRegistros();
    let modifCount = 0;
    todosRegs.forEach(r => {
      const matchCar = (r.carreraAreaKey === carreraKey || r.areaKey === carreraKey || normalizarCadena(r.carrera) === normalizarCadena(carreraKey));
      if (matchCar && r.nivel === nivelNom && (r.paralelo || 'A') === (paralelo || 'A') && String(r.gestion) === String(_gestionActiva)) {
        r.estado = 'PUBLICADO';
        r.fechaModificacion = new Date().toISOString();
        modifCount++;
      }
    });
    setRegistros(todosRegs);
    alert('Calificaciones del curso publicadas con éxito.');
    renderSubtabAdminContenido();
  }
  window.publicarNotasCursoDirector = publicarNotasCursoDirector;

  async function publicarRegistroDocente() {
    if (!_registroActivo || !_detallesActivos) return;
    if (_registroActivo.bloqueado) {
      alert('Este registro se encuentra BLOQUEADO por la Dirección.');
      return;
    }
    const conf = confirm(`¿Confirmas que deseas PUBLICAR las calificaciones de ${_registroActivo.carrera} - ${_registroActivo.modulo}?\n\nAl publicar, el estado cambiará a NOTAS PUBLICADAS y quedará formalizado ante la Dirección.`);
    if (!conf) return;

    _registroActivo.estado = 'PUBLICADO';
    _registroActivo.fechaModificacion = new Date().toISOString();
    await guardarRegistroCalificaciones(true);
    await registrarAuditoria(_registroActivo.id, 'PUBLICAR_DOCENTE', 'Calificaciones publicadas oficialmente por el docente.');
    await sincronizarCalifGoogleSheet('cambiar-estado-calificaciones', {
      idRegistro: _registroActivo.id,
      nuevoEstado: 'PUBLICADO',
      detalle: 'Calificaciones publicadas por docente'
    });
    alert('Calificaciones publicadas con éxito. Estado: NOTAS PUBLICADAS.');
    renderPlanillaEvaluacion(_registroActivo, _detallesActivos, 'docente');
  }
  window.publicarRegistroDocente = publicarRegistroDocente;

